INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_09','V306','阮明',9,'办理退款需要打印纸质付款凭证，还是只提供手机截图就行？','bàn lǐ tuì kuǎn xū yào dǎ yìn zhǐ zhì fù kuǎn píng zhèng， hái shì zhǐ tí gōng shǒu jī jié tú jiù xíng？','Vậy để làm thủ tục hoàn tiền thì con cần in hóa đơn thanh toán giấy, hay chỉ cần gửi ảnh chụp màn hình điện thoại là được ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_10','V306','宿管阿姨',10,'不用打印纸质单据，直接把当时的付款截图微信发给我即可。','bù yòng dǎ yìn zhǐ zhì dān jù， zhí jiē bǎ dāng shí de fù kuǎn jié tú wēi xìn fā gěi wǒ jí kě。','Không cần in hóa đơn giấy đâu, con cứ gửi ảnh chụp lúc thanh toán qua WeChat cho cô là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_11','V306','阮明',11,'截图我马上调取发送，大概多久能完成退款到账？','jié tú wǒ mǎ shàng diào qǔ fā sòng， dà gài duō jiǔ néng wán chéng tuì kuǎn dào zhàng？','Vậy con lấy ảnh gửi ngay đây ạ, chắc khoảng bao lâu thì tiền hoàn về ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_12','V306','宿管阿姨',12,'统一每周五集中处理退款申请，最晚本周五资金原路退回。','tǒng yī měi zhōu wǔ jí zhōng chǔ lǐ tuì kuǎn shēn qǐng， zuì wǎn běn zhōu wǔ zī jīn yuán lù tuì huí。','Cứ thứ Sáu hàng tuần là xử lý hoàn tiền tập trung một lần, chậm nhất thứ Sáu tuần này tiền sẽ hoàn về đúng chỗ cũ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_13','V306','阮明',13,'我明白需要等待统一处理，辛苦阿姨帮忙登记上报就行。','wǒ míng bái xū yào děng dài tǒng yī chǔ lǐ， xīn kǔ ā yí bāng máng dēng jì shàng bào jiù xíng。','Con hiểu rồi, phải chờ xử lý chung, cô vất vả giúp con đăng ký báo cáo là được ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_14','V306','宿管阿姨',14,'小事，下次洗衣前记得多充一点余额，避免中途停机。','xiǎo shì， xià cì xǐ yī qián jì de duō chōng yì diǎn yú é， bì miǎn zhōng tú tíng jī。','Chuyện nhỏ thôi, lần sau giặt đồ nhớ nạp thêm chút tiền vào, để khỏi bị dừng giữa chừng nữa nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L306_15','V306','阮明',15,'好的，辛苦阿姨啦！','hǎo de， xīn kǔ ā yí la！','Dạ vâng, cô vất vả rồi ạ!','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT307','S104','Gọi món mang đi ở quán gần trường',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V307','SIT307','P1','suon_se','tuy_y',NULL,'国内街边小吃支持自由调整口味、增减食材，常规外带打包无需额外收费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_01','V307','阮明',1,'你好，我要一份杂粮煎饼，打包外带哦。','nǐ hǎo， wǒ yào yī fèn zá liáng jiān bǐng， dǎ bāo wài dài ó。','Chào chị, cho em một cái bánh kếp ngũ cốc, gói mang đi nha.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_02','V307','店员',2,'好嘞，要不要加烤肠、生菜这些配菜呀？','hǎo lei， yào bù yào jiā kǎo cháng、 shēng cài zhè xiē pèi cài ya？','Được luôn, có cho thêm xúc xích với xà lách không em?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_03','V307','阮明',3,'加一根烤肠就好，少放辣椒吧，我不太能吃辣。','jiā yī gēn kǎo cháng jiù hǎo， shǎo fàng là jiāo ba， wǒ bù tài néng chī là。','Cho em một cây xúc xích thôi, ớt bớt lại giùm em, em không ăn cay được lắm.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_04','V307','店员',4,'没问题，微辣口味，两分钟就好哈。','méi wèn tí， wēi là kǒu wèi， liǎng fēn zhōng jiù hǎo hā。','Không sao, vị cay nhẹ nha, hai phút là xong liền.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_05','V307','阮明',5,'麻烦帮我封紧一点，我带回宿舍吃。','má fán bāng wǒ fēng jǐn yì diǎn， wǒ dài huí sù shè chī。','Chị gói kỹ giùm em nha, em mang về ký túc xá ăn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_06','V307','店员',6,'放心，肯定给你包得严严实实的。','fàng xīn， kěn dìng gěi nǐ bāo dé yán yán shí shí de。','Yên tâm đi, chị gói kín mít cho em luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L307_07','V307','阮明',7,'谢谢老板！','xiè xiè lǎo bǎn！','Cảm ơn chị nha!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT308','S104','Báo dị ứng thực phẩm khi đặt món online',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V308','SIT308','P1','twist','ban_chinh_thuc',NULL,'国内外卖平台的用餐备注优先级很高，食材过敏、特殊口味等需求，正规商家都会优先遵从。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_01','V308','阮明',1,'你好，我刚下的订单，有重要的忌口需要备注。','nǐ hǎo， wǒ gāng xià de dìng dān， yǒu zhòng yào de jì kǒu xū yào bèi zhù。','Chào bạn, mình vừa đặt đơn hàng, có một yêu cầu kiêng cữ quan trọng cần ghi chú thêm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_02','V308','客服',2,'您好，请您说明具体要求，我们同步给后厨。','nín hǎo， qǐng nín shuō míng jù tǐ yāo qiú， wǒ men tóng bù gěi hòu chú。','Chào bạn, bạn cứ nói rõ yêu cầu cụ thể, chúng tôi sẽ báo ngay cho bếp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_03','V308','阮明',3,'我严重对花生过敏，餐品里千万不要放任何花生制品啊。','wǒ yán zhòng duì huā shēng guò mǐn， cān pǐn lǐ qiān wàn bú yào fàng rèn hé huā shēng zhì pǐn a。','Mình bị dị ứng đậu phộng rất nặng, món ăn tuyệt đối không được cho bất kỳ chế phẩm nào từ đậu phộng vào nhé.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_04','V308','客服',4,'好的，已经为您重点备注忌口花生。','hǎo de， yǐ jīng wèi nín zhòng diǎn bèi zhù jì kǒu huā shēng。','Vâng, chúng tôi đã ghi chú đặc biệt về việc kiêng đậu phộng cho bạn rồi ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_05','V308','阮明',5,'之前有商家忽略备注，差点出问题呢。','zhī qián yǒu shāng jiā hū lüè bèi zhù， chà diǎn chū wèn tí ne。','Trước đây có quán bỏ qua ghi chú của mình, suýt thì gặp chuyện đó.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_06','V308','客服',6,'非常抱歉让您有顾虑，我们会单独叮嘱后厨的。','fēi cháng bào qiàn ràng nín yǒu gù lǜ， wǒ men huì dān dú dīng zhǔ hòu chú de。','Chúng tôi thành thật xin lỗi vì đã khiến bạn lo lắng, chúng tôi sẽ dặn riêng bên bếp cẩn thận.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L308_07','V308','阮明',7,'那就麻烦你们多留意一下。','nà jiù má fán nǐ men duō liú yì yī xià。','Vậy phiền các bạn để ý kỹ thêm giúp mình nhé.',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT309','S101','Hỏi hạn sử dụng và bảo quản thực phẩm',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V309','SIT309','P1','suon_se','tuy_y',NULL,'食品分常温、冷藏两类储存方式，错误存放会大幅缩短保质期，是日常收纳的基本常识。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_01','V309','阮明',1,'你好，我想问一下这款酸奶的保质期是多久呀？','nǐ hǎo， wǒ xiǎng wèn yī xià zhè kuǎn suān nǎi de bǎo zhì qī shì duō jiǔ ya？','Chào chị, cho em hỏi hạn sử dụng của loại sữa chua này là bao lâu vậy ạ?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_02','V309','店员',2,'这款常温酸奶保质期三个月，不用放冰箱的。','zhè kuǎn cháng wēn suān nǎi bǎo zhì qī sān gè yuè， bù yòng fàng bīng xiāng de。','Loại sữa chua để nhiệt độ thường này hạn dùng ba tháng, không cần bỏ tủ lạnh đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_03','V309','阮明',3,'那开封之后可以放多久呢？','nà kāi fēng zhī hòu kě yǐ fàng duō jiǔ ne？','Vậy sau khi mở nắp thì để được bao lâu ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_04','V309','店员',4,'开封后最好当天喝完，放久容易变质哦。','kāi fēng hòu zuì hǎo dàng tiān hē wán， fàng jiǔ róng yì biàn zhì ó。','Mở nắp rồi thì tốt nhất uống hết trong ngày, để lâu dễ bị hỏng lắm.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_05','V309','阮明',5,'原来是这样，常温存放就可以是吧？','yuán lái shì zhè yàng， cháng wēn cún fàng jiù kě yǐ shì ba？','À ra vậy, để ở nhiệt độ thường là được đúng không chị?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_06','V309','店员',6,'对的，避开阳光暴晒就行，很方便的。','duì de， bì kāi yáng guāng pù shài jiù xíng， hěn fāng biàn de。','Đúng rồi, chỉ cần tránh ánh nắng chiếu trực tiếp là được, tiện lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L309_07','V309','阮明',7,'清楚了，谢谢你！','qīng chǔ le， xiè xiè nǐ！','Em rõ rồi ạ, cảm ơn chị!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT310','S105','Thương lượng với hàng xóm về tiếng ồn',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V310','SIT310','P1','suon_se','ban_chinh_thuc',NULL,'国内高校宿舍普遍默认夜间十点为安静作息时间，邻里噪音问题友好协商即可解决。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_01','V310','阮明',1,'同学你好，不好意思打扰你一下哈。','tóng xué nǐ hǎo， bù hǎo yì sī dǎ rǎo nǐ yī xià hā。','Chào bạn, xin lỗi làm phiền bạn một chút nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_02','V310','邻居',2,'没事的，你有什么事直接说就好呀。','méi shì de， nǐ yǒu shén me shì zhí jiē shuō jiù hǎo ya。','Không sao đâu, bạn có gì cứ nói thẳng ra nhé.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_03','V310','阮明',3,'我晚上要复习备考，你们宿舍声音稍微有点大呢。','wǒ wǎn shàng yào fù xí bèi kǎo， nǐ men sù shè shēng yīn shāo wēi yǒu diǎn dà ne。','Tối nay mình cần ôn bài chuẩn bị thi, phòng các bạn hơi ồn một chút.','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_04','V310','邻居',4,'天啊，真的不好意思，我们没注意音量。','tiān a， zhēn de bù hǎo yì sī， wǒ men méi zhù yì yīn liàng。','Trời ơi, thật xin lỗi bạn nha, tụi mình không để ý âm lượng.','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_05','V310','阮明',5,'没关系的，就是希望晚上十点后可以安静一点。','méi guān xì de， jiù shì xī wàng wǎn shàng shí diǎn hòu kě yǐ ān jìng yì diǎn。','Không sao đâu, mình chỉ mong sau mười giờ tối có thể yên tĩnh hơn một chút thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_06','V310','邻居',6,'没问题，我们马上小声，之后一定注意！','méi wèn tí， wǒ men mǎ shàng xiǎo shēng， zhī hòu yí dìng zhù yì！','Không vấn đề gì, tụi mình nhỏ tiếng ngay đây, sau này nhất định sẽ chú ý!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L310_07','V310','阮明',7,'太感谢你的理解啦！','tài gǎn xiè nǐ de lǐ jiě la！','Cảm ơn bạn đã thông cảm nhiều lắm nha!','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT311','S106','Xin phép vào lớp muộn',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V311','SIT311','P1','suon_se','ban_chinh_thuc',NULL,'国内课堂迟到必须主动致歉并说明原因，征得老师同意后方可进入教室，是基本课堂礼仪。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_01','V311','阮明',1,'老师对不起，我上课迟到了，非常抱歉！','lǎo shī duì bù qǐ， wǒ shàng kè chí dào le， fēi cháng bào qiàn！','Thưa thầy, em xin lỗi vì đã đến lớp trễ ạ, em thật sự rất xin lỗi!',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_02','V311','老师',2,'怎么迟到了呢？是什么原因造成的？','zěn me chí dào le ne？ shì shén me yuán yīn zào chéng de？','Sao lại trễ vậy? Nguyên nhân là do đâu?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_03','V311','阮明',3,'我早上出门晚了，遇上堵车，耽误了时间。','wǒ zǎo shàng chū mén wǎn le， yù shàng dǔ chē， dān wù le shí jiān。','Dạ sáng nay em ra khỏi nhà trễ, lại gặp kẹt xe, nên bị lỡ mất thời gian ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_04','V311','老师',4,'下次一定要把控好时间，不要再迟到了。','xià cì yí dìng yào bǎ kòng hǎo shí jiān， bú yào zài chí dào le。','Lần sau nhất định phải sắp xếp thời gian cho tốt, đừng để trễ nữa nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_05','V311','阮明',5,'我记住了，以后肯定提前出门。','wǒ jì zhù le， yǐ hòu kěn dìng tí qián chū mén。','Dạ em nhớ rồi ạ, sau này chắc chắn em sẽ ra khỏi nhà sớm hơn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_06','V311','老师',6,'行，快进来入座听课吧，不要耽误学习。','xíng， kuài jìn lái rù zuò tīng kè ba， bú yào dān wù xué xí。','Được rồi, mau vào chỗ ngồi nghe giảng đi, đừng để ảnh hưởng việc học.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L311_07','V311','阮明',7,'谢谢老师谅解！','xiè xiè lǎo shī liàng jiě！','Em cảm ơn thầy đã thông cảm ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT312','S106','Xin nghỉ học vì lý do cá nhân',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V312','SIT312','P1','suon_se','ban_chinh_thuc',NULL,'国内高校禁止无故缺课，所有缺勤都需要提前报备请假，否则会记录考勤扣分。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_01','V312','阮明',1,'辅导员您好，我想申请今天下午的事假。','fǔ dǎo yuán nín hǎo， wǒ xiǎng shēn qǐng jīn tiān xià wǔ de shì jià。','Thưa thầy, em muốn xin phép nghỉ việc riêng chiều nay ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_02','V312','辅导员',2,'可以的，简单说一下请假的原因吧。','kě yǐ de， jiǎn dān shuō yī xià qǐng jià de yuán yīn ba。','Được, em cứ nói qua lý do xin nghỉ nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_03','V312','阮明',3,'我有重要的个人私事需要处理，没办法延后。','wǒ yǒu zhòng yào de gè rén sī shì xū yào chǔ lǐ， méi bàn fǎ yán hòu。','Dạ em có việc riêng quan trọng cần giải quyết, không thể trì hoãn được ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_04','V312','辅导员',4,'了解了，我给你登记考勤，准予请假。','liǎo jiě le， wǒ gěi nǐ dēng jì kǎo qín， zhǔn yǔ qǐng jià。','Thầy hiểu rồi, để thầy ghi nhận vào điểm danh, đồng ý cho em nghỉ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_05','V312','阮明',5,'谢谢老师，落下的课程我会及时补回来的。','xiè xiè lǎo shī， là xià de kè chéng wǒ huì jí shí bǔ huí lái de。','Em cảm ơn thầy, phần bài học bị lỡ em sẽ bổ sung kịp thời ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_06','V312','辅导员',6,'一定要跟上进度，不要拖欠学习内容。','yí dìng yào gēn shàng jìn dù， bú yào tuō qiàn xué xí nèi róng。','Nhớ phải theo kịp tiến độ, đừng để nợ bài học nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L312_07','V312','阮明',7,'我明白的，辛苦老师了！','wǒ míng bái de， xīn kǔ lǎo shī le！','Dạ em hiểu rồi ạ, thầy vất vả rồi!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT313','S107','Xin gia hạn nộp bài tập',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V313','SIT313','P1','twist','ban_chinh_thuc',NULL,'大学作业延期属于特殊情况，老师会酌情处理，但不支持频繁、长期延期；超规定延期时限会扣除课程平时成绩。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_01','V313','阮明',1,'老师您好，占用您一点课余时间，我想跟您申请课程作业延期提交。','lǎo shī nín hǎo， zhàn yòng nín yì diǎn kè yú shí jiān， wǒ xiǎng gēn nín shēn qǐng kè chéng zuò yè yán qī tí jiāo。','Chào cô ạ, em xin phép chiếm dụng chút thời gian ngoài giờ của cô, em muốn xin cô cho gia hạn nộp bài tập.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_02','V313','老师',2,'你先简单说明理由，课堂规定无故拖延作业提交时间是不允许的哦。','nǐ xiān jiǎn dān shuō míng lǐ yóu， kè táng guī dìng wú gù tuō yán zuò yè tí jiāo shí jiān shì bù yǔn xǔ de ó。','Em nói ngắn gọn lý do trước đã, quy định trên lớp là không được tự ý trì hoãn nộp bài đâu nhé.','AM03');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_03','V313','阮明',3,'昨天一整天突发肠胃不适，头晕乏力卧床休息，完全没有精力动笔写作业。','zuó tiān yī zhěng tiān tū fā cháng wèi bù shì， tóu yūn fá lì wò chuáng xiū xī， wán quán méi yǒu jīng lì dòng bǐ xiě zuò yè。','Hôm qua cả ngày em bị đau bụng rối loạn tiêu hóa, chóng mặt mệt lả phải nằm nghỉ, hoàn toàn không còn sức để làm bài.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_04','V313','老师',4,'身体不舒服我可以理解，生病属于合理特殊情况，不过延期有严格时限要求。','shēn tǐ bù shū fú wǒ kě yǐ lǐ jiě， shēng bìng shǔ yú hé lǐ tè shū qíng kuàng， bù guò yán qī yǒu yán gé shí xiàn yāo qiú。','Cô hiểu chuyện sức khỏe không tốt, ốm đau là trường hợp đặc biệt hợp lý, nhưng gia hạn thì có quy định thời hạn rất nghiêm ngặt.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_05','V313','阮明',5,'我原本计划今天傍晚准时上交，现在还差一半内容没能完成。','wǒ yuán běn jì huà jīn tiān bàng wǎn zhǔn shí shàng jiāo， xiàn zài hái chà yí bàn nèi róng méi néng wán chéng。','Em vốn định chiều tối nay nộp đúng hạn, nhưng giờ vẫn còn thiếu một nửa nội dung chưa làm xong.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_06','V313','老师',6,'按照学院统一规定，单次作业最多只能延期一天，不能无限延后。','àn zhào xué yuàn tǒng yī guī dìng， dān cì zuò yè zuì duō zhǐ néng yán qī yī tiān， bù néng wú xiàn yán hòu。','Theo quy định chung của khoa, mỗi bài tập chỉ được gia hạn tối đa một ngày, không thể lùi vô thời hạn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_07','V313','阮明',7,'只延期一天对我来说完全足够，今晚我熬夜赶工，保证完整写完所有内容。','zhǐ yán qī yī tiān duì wǒ lái shuō wán quán zú gòu， jīn wǎn wǒ áo yè gǎn gōng， bǎo zhèng wán zhěng xiě wán suǒ yǒu nèi róng。','Gia hạn một ngày là quá đủ với em rồi, tối nay em sẽ thức khuya làm cho xong, đảm bảo hoàn thành đầy đủ hết nội dung.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_08','V313','老师',8,'这次看你身体不适特殊通融一次，往后不管任何理由都尽量按时完成。','zhè cì kàn nǐ shēn tǐ bù shì tè shū tōng róng yī cì， wǎng hòu bù guǎn rèn hé lǐ yóu dōu jǐn liàng àn shí wán chéng。','Lần này thấy em ốm nên cô châm chước cho một lần, sau này dù lý do gì cũng phải cố gắng hoàn thành đúng hạn nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_09','V313','阮明',9,'我记下老师的提醒，下次一定提前规划时间，不会再出现延期情况。','wǒ jì xià lǎo shī de tí xǐng， xià cì yí dìng tí qián guī huà shí jiān， bú huì zài chū xiàn yán qī qíng kuàng。','Em ghi nhớ lời nhắc của cô rồi ạ, lần sau em nhất định sẽ sắp xếp thời gian trước, không để xảy ra chuyện trễ hạn nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_10','V313','老师',10,'延期提交的作业明天傍晚六点前必须交到办公室，逾期依旧会扣除平时分。','yán qī tí jiāo de zuò yè míng tiān bàng wǎn liù diǎn qián bì xū jiāo dào bàn gōng shì， yú qī yī jiù huì kòu chú píng shí fēn。','Bài nộp trễ thì trước sáu giờ chiều mai phải mang lên văn phòng, nộp muộn hơn nữa vẫn sẽ bị trừ điểm chuyên cần đấy.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_11','V313','阮明',11,'我会定好闹钟准时送达，不会错过截止时间。','wǒ huì dìng hǎo nào zhōng zhǔn shí sòng dá， bú huì cuò guò jié zhǐ shí jiān。','Em sẽ hẹn giờ báo thức để nộp đúng giờ, không để lỡ hạn chót đâu ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_12','V313','老师',12,'作业提交后我会优先批改，有错误再单独跟你讲解。','zuò yè tí jiāo hòu wǒ huì yōu xiān pī gǎi， yǒu cuò wù zài dān dú gēn nǐ jiǎng jiě。','Sau khi nộp bài cô sẽ ưu tiên chấm trước, chỗ nào sai cô sẽ giảng riêng cho em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_13','V313','阮明',13,'太感谢老师体谅我的身体状况，我一定认真完成作业。','tài gǎn xiè lǎo shī tǐ liàng wǒ de shēn tǐ zhuàng kuàng， wǒ yí dìng rèn zhēn wán chéng zuò yè。','Em cảm ơn cô rất nhiều vì đã thông cảm cho tình trạng sức khỏe của em, em nhất định sẽ làm bài thật nghiêm túc.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_14','V313','老师',14,'好好休息，别过度熬夜伤身体。','hǎo hǎo xiū xī， bié guò dù áo yè shāng shēn tǐ。','Nghỉ ngơi cho khỏe đi, đừng thức khuya quá mà hại sức khỏe.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L313_15','V313','阮明',15,'好的，谢谢老师！','hǎo de， xiè xiè lǎo shī！','Vâng ạ, em cảm ơn cô!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT314','S107','Trao đổi phân công trong làm việc nhóm',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V314','SIT314','P1','suon_se','tuy_y',NULL,'国内大学小组作业讲究全员参与、公平分工，团队协作度是评分的重要标准。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_01','V314','张浩',1,'我们小组作业还没分工，今天赶紧定一下吧？','wǒ men xiǎo zǔ zuò yè hái méi fēn gōng， jīn tiān gǎn jǐn dìng yī xià ba？','Nhóm mình vẫn chưa phân công gì cả, hôm nay chốt luôn đi nhé?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_02','V314','阮明',2,'好呀，我们按各自特长分工，效率会更高。','hǎo ya， wǒ men àn gè zì tè cháng fēn gōng， xiào lǜ huì gèng gāo。','Ừ được đó, mình phân theo sở trường của từng người, làm sẽ hiệu quả hơn.','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_03','V314','张浩',3,'我擅长搜集资料和写文稿，PPT制作你可以吗？','wǒ shàn cháng sōu jí zī liào hé xiě wén gǎo，PPT zhì zuò nǐ kě yǐ ma？','Mình giỏi tìm tài liệu với viết nội dung, còn làm PPT cậu ổn không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_04','V314','阮明',4,'没问题，我很擅长做PPT，这个交给我。','méi wèn tí， wǒ hěn shàn cháng zuò PPT， zhè ge jiāo gěi wǒ。','Không thành vấn đề, mình làm PPT khá lắm, để đó cho mình.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_05','V314','张浩',5,'那最后课堂汇报，我们两个人一起配合。','nà zuì hòu kè táng huì bào， wǒ men liǎng gè rén yì qǐ pèi hé。','Vậy phần thuyết trình trên lớp cuối cùng thì hai đứa mình phối hợp làm chung nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_06','V314','阮明',6,'可以，我们做完互相检查，避免出错。','kě yǐ， wǒ men zuò wán hù xiāng jiǎn chá， bì miǎn chū cuò。','Được đó, làm xong mình kiểm tra chéo cho nhau, tránh sai sót.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L314_07','V314','张浩',7,'完美，那我们各自开工！','wán měi， nà wǒ men gè zì kāi gōng！','Hoàn hảo, vậy mỗi đứa bắt tay vào làm phần của mình thôi!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT315','S106','Thuyết trình trước lớp, xin lỗi vì thiếu chuẩn bị',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V315','SIT315','P1','that_bai_nhe','ban_chinh_thuc',NULL,'国内课堂展示允许轻微失误，主动诚恳认错、复盘问题，不会大幅扣分。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_01','V315','阮明',1,'老师、各位同学，非常抱歉，我本次的课堂汇报准备不足。','lǎo shī、 gè wèi tóng xué， fēi cháng bào qiàn， wǒ běn cì de kè táng huì bào zhǔn bèi bù zú。','Thưa cô, các bạn, em thật sự xin lỗi vì bài thuyết trình lần này em chuẩn bị chưa kỹ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_02','V315','老师',2,'没关系，正常展示就好，说说问题在哪？','méi guān xì， zhèng cháng zhǎn shì jiù hǎo， shuō shuō wèn tí zài nǎ？','Không sao đâu, cứ trình bày bình thường thôi, em nói xem vấn đề nằm ở đâu?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_03','V315','阮明',3,'我前期资料整理不够细致，内容细节缺失很多。','wǒ qián qī zī liào zhěng lǐ bù gòu xì zhì， nèi róng xì jié quē shī hěn duō。','Giai đoạn đầu em tổng hợp tài liệu chưa được kỹ càng, nên nội dung bị thiếu khá nhiều chi tiết.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_04','V315','阮明',4,'这是我的疏忽，没有提前充分打磨内容。','zhè shì wǒ de shū hū， méi yǒu tí qián chōng fèn dǎ mó nèi róng。','Đây là sơ suất của em, em đã không chuẩn bị nội dung kỹ lưỡng từ trước.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_05','V315','老师',5,'敢于正视问题就很好，下次提前准备充分就行。','gǎn yú zhèng shì wèn tí jiù hěn hǎo， xià cì tí qián zhǔn bèi chōng fèn jiù xíng。','Dám nhìn thẳng vào vấn đề như vậy là tốt rồi, lần sau chuẩn bị đầy đủ trước là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L315_06','V315','阮明',6,'我记住了，感谢老师和同学们的包容！','wǒ jì zhù le， gǎn xiè lǎo shī hé tóng xué men de bāo róng！','Em ghi nhớ rồi ạ, em cảm ơn cô và các bạn đã thông cảm cho em!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT316','S107','Hỏi lại bài giảng chưa hiểu với giáo viên',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V316','SIT316','P1','suon_se','ban_chinh_thuc',NULL,'国内高校老师普遍鼓励课后答疑，主动提问是被认可的良好学习习惯。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_01','V316','阮明',1,'老师您好，刚才课堂讲的知识点我没太听懂。','lǎo shī nín hǎo， gāng cái kè táng jiǎng de zhī shí diǎn wǒ méi tài tīng dǒng。','Chào cô, phần kiến thức cô vừa giảng trên lớp em chưa hiểu rõ lắm ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_02','V316','老师',2,'哪一部分不理解？我再给你讲一遍。','nǎ yī bù fèn bù lǐ jiě？ wǒ zài gěi nǐ jiǎng yī biàn。','Phần nào em chưa hiểu? Cô giảng lại cho em một lần nữa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_03','V316','阮明',3,'就是公式的运用逻辑，我还是有点模糊。','jiù shì gōng shì de yùn yòng luó jí， wǒ hái shì yǒu diǎn mó hú。','Là logic áp dụng công thức ấy ạ, em vẫn thấy hơi mơ hồ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_04','V316','老师',4,'没事，我简单梳理一遍，你仔细听。','méi shì， wǒ jiǎn dān shū lǐ yī biàn， nǐ zǐ xì tīng。','Không sao, cô tóm tắt lại một lượt, em nghe cho kỹ nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_05','V316','阮明',5,'好的，麻烦老师费心讲解了。','hǎo de， má fán lǎo shī fèi xīn jiǎng jiě le。','Vâng ạ, phiền cô giảng giải giúp em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_06','V316','老师',6,'不懂就问是好习惯，不用不好意思。','bù dǒng jiù wèn shì hǎo xí guàn， bù yòng bù hǎo yì sī。','Không hiểu thì hỏi là thói quen tốt, không cần ngại đâu.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L316_07','V316','阮明',7,'听完我完全懂了，谢谢老师！','tīng wán wǒ wán quán dǒng le， xiè xiè lǎo shī！','Nghe xong em hiểu hết rồi ạ, em cảm ơn cô!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT317','S108','Hỏi quy định phòng thi',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V317','SIT317','P1','suon_se','chinh_thuc',NULL,'国内标准化考试严禁携带私人物品入场，违规携带会被判定为考试违纪。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_01','V317','阮明',1,'老师您好，我想咨询一下本次期末考试的考场规则。','lǎo shī nín hǎo， wǒ xiǎng zī xún yī xià běn cì qī mò kǎo shì de kǎo chǎng guī zé。','Chào thầy/cô, tôi muốn hỏi về quy định phòng thi của kỳ thi cuối kỳ lần này.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_02','V317','监考老师',2,'你有不清楚的地方可以直接提问。','nǐ yǒu bù qīng chǔ de dì fāng kě yǐ zhí jiē tí wèn。','Có gì chưa rõ bạn cứ hỏi trực tiếp.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_03','V317','阮明',3,'请问考试期间可以自带草稿纸和文具吗？','qǐng wèn kǎo shì qī jiān kě yǐ zì dài cǎo gǎo zhǐ hé wén jù ma？','Xin hỏi trong lúc thi có được mang theo giấy nháp và dụng cụ học tập riêng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_04','V317','监考老师',4,'不可以，考场会统一发放所有考试用品。','bù kě yǐ， kǎo chǎng huì tǒng yī fā fàng suǒ yǒu kǎo shì yòng pǐn。','Không được, phòng thi sẽ phát thống nhất tất cả vật dụng cần thiết cho kỳ thi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_05','V317','阮明',5,'那电子手表需要摘下来存放吗？','nà diàn zi shǒu biǎo xū yào zhāi xià lái cún fàng ma？','Vậy đồng hồ điện tử có cần tháo ra và cất riêng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_06','V317','监考老师',6,'是的，所有电子设备都需统一收纳。','shì de， suǒ yǒu diàn zi shè bèi dōu xū tǒng yī shōu nà。','Đúng vậy, tất cả thiết bị điện tử đều phải được thu gom cất giữ tập trung.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L317_07','V317','阮明',7,'我清楚所有规则了，谢谢老师！','wǒ qīng chǔ suǒ yǒu guī zé le， xiè xiè lǎo shī！','Tôi đã nắm rõ hết các quy định rồi, cảm ơn thầy/cô!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT318','S108','Xem điểm thi trên hệ thống bị sai, hỏi lại giáo viên',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V318','SIT318','P1','twist','ban_chinh_thuc',NULL,'校园教务系统偶有BUG，学生成绩最终以老师线下备案记录为准，可随时核实修正。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_01','V318','阮明',1,'老师您好，我想核实一下我的课程期末成绩。','lǎo shī nín hǎo， wǒ xiǎng hé shí yī xià wǒ de kè chéng qī mò chéng jì。','Chào cô, em muốn xác nhận lại điểm cuối kỳ của môn học của em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_02','V318','老师',2,'好的，具体是什么问题？','hǎo de， jù tǐ shì shén me wèn tí？','Được, cụ thể là vấn đề gì?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_03','V318','阮明',3,'我所有作业、考勤、考试都正常完成，但系统显示无成绩。','wǒ suǒ yǒu zuò yè、 kǎo qín、 kǎo shì dōu zhèng cháng wán chéng， dàn xì tǒng xiǎn shì wú chéng jì。','Em đã hoàn thành đầy đủ bài tập, điểm danh và thi cử, nhưng hệ thống lại hiển thị chưa có điểm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_04','V318','老师',4,'应该是教务系统录入卡顿，出现数据异常了。','yīng gāi shì jiào wù xì tǒng lù rù kǎ dùn， chū xiàn shù jù yì cháng le。','Chắc là do hệ thống giáo vụ nhập liệu bị lỗi, nên dữ liệu xuất hiện bất thường.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_05','V318','阮明',5,'我一直担心是自己漏交作业，心里很不安。','wǒ yì zhí dān xīn shì zì jǐ lòu jiāo zuò yè， xīn lǐ hěn bù ān。','Em cứ lo mãi là do mình lỡ thiếu bài tập nào đó, trong lòng thấy bất an quá.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_06','V318','老师',6,'你放心，我手动核对备案，重新给你录入成绩。','nǐ fàng xīn， wǒ shǒu dòng hé duì bèi àn， chóng xīn gěi nǐ lù rù chéng jì。','Em yên tâm, cô sẽ đối chiếu thủ công theo hồ sơ lưu, rồi nhập lại điểm cho em.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L318_07','V318','阮明',7,'太感谢老师帮忙处理了！','tài gǎn xiè lǎo shī bāng máng chǔ lǐ le！','Em cảm ơn cô nhiều lắm vì đã giúp em xử lý chuyện này!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT319','S108','Xin phúc khảo bài thi',NULL,'C1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V319','SIT319','P1','suon_se','chinh_thuc',NULL,'国内高校成绩复核仅核查卷面分数统计错误，不重新评判答题内容，是正规申诉渠道；复核结果统一公示，具备官方效力。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_01','V319','阮明',1,'老师您好，今天来找您，是想正式提交本次期末试卷成绩复核申请。','lǎo shī nín hǎo， jīn tiān lái zhǎo nín， shì xiǎng zhèng shì tí jiāo běn cì qī mò shì juàn chéng jì fù hé shēn qǐng。','Chào thầy, hôm nay tôi đến gặp thầy là để chính thức nộp đơn xin phúc khảo điểm bài thi cuối kỳ lần này.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_02','V319','老师',2,'先坐，我先跟你确认，你清楚学校成绩复核的具体范围和规则吗？','xiān zuò， wǒ xiān gēn nǐ què rèn， nǐ qīng chǔ xué xiào chéng jì fù hé de jù tǐ fàn wéi hé guī zé ma？','Mời ngồi, trước tiên tôi xác nhận lại với bạn, bạn có nắm rõ phạm vi và quy định phúc khảo điểm của trường không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_03','V319','阮明',3,'只听说可以核对卷面总分统计，不能重新评判答题内容，细节了解不多。','zhǐ tīng shuō kě yǐ hé duì juàn miàn zǒng fēn tǒng jì， bù néng chóng xīn píng pàn dá tí nèi róng， xì jié liǎo jiě bù duō。','Tôi chỉ nghe nói là có thể đối chiếu lại tổng điểm bài thi, chứ không được chấm lại nội dung bài làm, chi tiết thì tôi chưa nắm rõ lắm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_04','V319','老师',4,'没错，复核仅检查每道小题得分相加是否计算错误，不会更改主观题打分。','méi cuò， fù hé jǐn jiǎn chá měi dào xiǎo tí dé fēn xiāng jiā shì fǒu jì suàn cuò wù， bú huì gēng gǎi zhǔ guān tí dǎ fēn。','Đúng vậy, phúc khảo chỉ kiểm tra xem việc cộng điểm từng câu có bị tính sai hay không, chứ không thay đổi cách chấm các câu tự luận.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_05','V319','阮明',5,'我自己对照参考答案预估的分数，和最终系统录入成绩差距很大，心里比较疑惑。','wǒ zì jǐ duì zhào cān kǎo dá àn yù gū de fēn shù， hé zuì zhōng xì tǒng lù rù chéng jì chā jù hěn dà， xīn lǐ bǐ jiào yí huò。','Tôi tự đối chiếu với đáp án tham khảo và ước tính điểm của mình, nhưng chênh lệch khá nhiều so với điểm hệ thống ghi nhận cuối cùng, nên tôi khá thắc mắc.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_06','V319','老师',6,'我理解你的顾虑，我可以协助你向学院教学办提交官方书面复核申请。','wǒ lǐ jiě nǐ de gù lǜ， wǒ kě yǐ xié zhù nǐ xiàng xué yuàn jiào xué bàn tí jiāo guān fāng shū miàn fù hé shēn qǐng。','Tôi hiểu những băn khoăn của bạn, tôi có thể hỗ trợ bạn nộp đơn phúc khảo chính thức bằng văn bản lên văn phòng đào tạo của khoa.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_07','V319','阮明',7,'提交申请的时候，需要附带什么证明材料，填写专用表格吗？','tí jiāo shēn qǐng de shí hòu， xū yào fù dài shén me zhèng míng cái liào， tián xiě zhuān yòng biǎo gé ma？','Khi nộp đơn thì có cần kèm theo giấy tờ chứng minh gì không, và có phải điền vào mẫu đơn riêng không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_08','V319','老师',8,'我这边给你打印统一的复核申请表，填写姓名、学号、科目和申请理由即可。','wǒ zhè biān gěi nǐ dǎ yìn tǒng yī de fù hé shēn qǐng biǎo， tián xiě xìng míng、 xué hào、 kē mù hé shēn qǐng lǐ yóu jí kě。','Bên tôi sẽ in cho bạn mẫu đơn phúc khảo thống nhất, bạn chỉ cần điền họ tên, mã số sinh viên, môn học và lý do xin phúc khảo là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_09','V319','阮明',9,'请问提交申请表之后，大概多久可以出具最终复核结果呢？','qǐng wèn tí jiāo shēn qǐng biǎo zhī hòu， dà gài duō jiǔ kě yǐ chū jù zuì zhōng fù hé jié guǒ ne？','Xin hỏi sau khi nộp đơn thì khoảng bao lâu sẽ có kết quả phúc khảo cuối cùng ạ?','AM04');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_10','V319','老师',10,'学院统一收集申请，三个工作日内完成卷面核对并公示修正后的成绩。','xué yuàn tǒng yī shōu jí shēn qǐng， sān gè gōng zuò rì nèi wán chéng juàn miàn hé duì bìng gōng shì xiū zhèng hòu de chéng jì。','Khoa sẽ thu thập đơn tập trung, trong vòng ba ngày làm việc sẽ hoàn tất đối chiếu bài thi và công bố điểm đã được điều chỉnh.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_11','V319','阮明',11,'如果复核后分数有调整，系统成绩会同步更新对吧？','rú guǒ fù hé hòu fēn shù yǒu tiáo zhěng， xì tǒng chéng jì huì tóng bù gēng xīn duì ba？','Nếu sau phúc khảo điểm có thay đổi thì điểm trên hệ thống cũng sẽ được cập nhật đồng bộ đúng không ạ?','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_12','V319','老师',12,'是的，核对出计算失误会直接修改教务系统内你的期末分数。','shì de， hé duì chū jì suàn shī wù huì zhí jiē xiū gǎi jiào wù xì tǒng nèi nǐ de qī mò fēn shù。','Đúng vậy, nếu phát hiện tính sai thì sẽ sửa trực tiếp điểm cuối kỳ của bạn trên hệ thống giáo vụ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_13','V319','阮明',13,'我现在填写申请表，麻烦老师帮忙转交教学办。','wǒ xiàn zài tián xiě shēn qǐng biǎo， má fán lǎo shī bāng máng zhuǎn jiāo jiào xué bàn。','Giờ tôi điền đơn luôn, phiền thầy giúp tôi chuyển lên văn phòng đào tạo.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_14','V319','老师',14,'放心，流程我全程跟进，有结果第一时间通知你。','fàng xīn， liú chéng wǒ quán chéng gēn jìn， yǒu jié guǒ dì yī shí jiān tōng zhī nǐ。','Yên tâm đi, tôi sẽ theo sát toàn bộ quy trình, có kết quả sẽ báo cho bạn ngay.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L319_15','V319','阮明',15,'辛苦老师费心办理，非常感谢！','xīn kǔ lǎo shī fèi xīn bàn lǐ， fēi cháng gǎn xiè！','Cảm ơn thầy đã vất vả lo liệu giúp tôi, tôi cảm kích lắm!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT320','S106','Mượn vở ghi chép của bạn vì nghỉ học',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V320','SIT320','P1','suon_se','tuy_y',NULL,'同学之间互借笔记、补全知识点是国内大学校园最普遍的互助行为。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_01','V320','阮明',1,'琪琪，我昨天请假缺课了，能借我一下你的课堂笔记吗？','qí qí， wǒ zuó tiān qǐng jià quē kè le， néng jiè wǒ yī xià nǐ de kè táng bǐ jì ma？','Kỳ Kỳ ơi, hôm qua tớ xin nghỉ nên bị lỡ buổi học, cho tớ mượn vở ghi chép của cậu được không?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_02','V320','李琪',2,'当然可以，我记得特别详细，重难点都标出来了。','dāng rán kě yǐ， wǒ jì de tè bié xiáng xì， zhòng nán diǎn dōu biāo chū lái le。','Được chứ, tớ ghi khá chi tiết đó, chỗ nào trọng tâm khó tớ đều đánh dấu hết rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_03','V320','阮明',3,'太好了，我刚好错过最重要的知识点。','tài hǎo le， wǒ gāng hǎo cuò guò zuì zhòng yào de zhī shí diǎn。','Tuyệt quá, đúng lúc tớ bị lỡ mất phần kiến thức quan trọng nhất luôn.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_04','V320','李琪',4,'没事，你慢慢看，看完再还我就行。','méi shì， nǐ màn màn kàn， kàn wán zài hái wǒ jiù xíng。','Không sao đâu, cậu cứ từ từ xem, xem xong trả lại tớ là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_05','V320','阮明',5,'太感谢了，有不懂的地方我再问你哈。','tài gǎn xiè le， yǒu bù dǒng de dì fāng wǒ zài wèn nǐ hā。','Cảm ơn cậu nhiều lắm, chỗ nào không hiểu tớ hỏi cậu thêm nha.','AM06');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_06','V320','李琪',6,'没问题，同学之间本来就该互相帮忙。','méi wèn tí， tóng xué zhī jiān běn lái jiù gāi hù xiāng bāng máng。','Không thành vấn đề, bạn bè vốn dĩ phải giúp đỡ lẫn nhau mà.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L320_07','V320','阮明',7,'真的太贴心啦！','zhēn de tài tiē xīn la！','Cậu tốt bụng ghê luôn á!','AM02');
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT321','S109','Đặt lịch khám qua ứng dụng',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V321','SIT321','P1','twist','ban_chinh_thuc',NULL,'国内公立医院热门科室号源紧张，必须提前线上预约，现场基本无剩余号。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_01','V321','阮明',1,'你好，我想在APP上预约今天的内科门诊。','nǐ hǎo， wǒ xiǎng zài APP shàng yù yuē jīn tiān de nèi kē mén zhěn。','Chào chị, em muốn đặt lịch khám nội khoa hôm nay qua ứng dụng ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_02','V321','客服',2,'您好，请问您需要普通号还是专家号？','nín hǎo， qǐng wèn nín xū yào pǔ tōng hào hái shì zhuān jiā hào？','Chào bạn, bạn muốn đặt số khám thường hay số khám chuyên gia ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_03','V321','阮明',3,'普通号就可以，我只是轻微头晕乏力。','pǔ tōng hào jiù kě yǐ， wǒ zhǐ shì qīng wēi tóu yūn fá lì。','Số khám thường là được rồi, em chỉ bị hơi chóng mặt với mệt thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_04','V321','客服',4,'非常抱歉，今天内科普通号已经全部约满了。','fēi cháng bào qiàn， jīn tiān nèi kē pǔ tōng hào yǐ jīng quán bù yuē mǎn le。','Rất xin lỗi, số khám thường khoa nội hôm nay đã hết chỗ rồi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_05','V321','阮明',5,'这样啊，那明天的号还有空位吗？','zhè yàng a， nà míng tiān de hào hái yǒu kòng wèi ma？','Vậy à, thế ngày mai còn chỗ trống không chị?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_06','V321','客服',6,'明天上午号源充足，我可以指导您预约。','míng tiān shàng wǔ hào yuán chōng zú， wǒ kě yǐ zhǐ dǎo nín yù yuē。','Sáng mai còn nhiều chỗ lắm, để chị hướng dẫn em đặt lịch nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L321_07','V321','阮明',7,'好的，麻烦你教我操作一下！','hǎo de， má fán nǐ jiāo wǒ cāo zuò yī xià！','Dạ được, phiền chị chỉ em thao tác với ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT322','S109','Đăng ký khoa khám phù hợp tại quầy',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V322','SIT322','P1','suon_se','ban_chinh_thuc',NULL,'医院科室划分精细，身体不适不确定科室，可咨询挂号窗口精准分诊，避免挂错号。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_01','V322','阮明',1,'你好，我最近经常头晕、睡眠不好，该挂什么科室？','nǐ hǎo， wǒ zuì jìn jīng cháng tóu yūn、 shuì mián bù hǎo， gāi guà shén me kē shì？','Chào chị, dạo này em hay bị chóng mặt, ngủ không ngon, vậy nên khám khoa nào ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_02','V322','工作人员',2,'你这个症状挂神经内科是最合适的。','nǐ zhè ge zhèng zhuàng guà shén jīng nèi kē shì zuì hé shì de。','Với triệu chứng như em thì khám khoa nội thần kinh là hợp nhất.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_03','V322','阮明',3,'那帮我挂一个今天下午的普通门诊吧。','nà bāng wǒ guà yí gè jīn tiān xià wǔ de pǔ tōng mén zhěn ba。','Vậy chị giúp em đăng ký khám thường chiều nay nhé.','AM07');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_04','V322','工作人员',4,'好的，请问使用医保结算还是自费？','hǎo de， qǐng wèn shǐ yòng yī bǎo jié suàn hái shì zì fèi？','Được rồi, em thanh toán bằng bảo hiểm y tế hay tự chi trả ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_05','V322','阮明',5,'我用学生医保结算。','wǒ yòng xué shēng yī bǎo jié suàn。','Em dùng bảo hiểm y tế sinh viên để thanh toán.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_06','V322','工作人员',6,'已为您挂号成功，请前往二楼诊室等候。','yǐ wèi nín guà hào chéng gōng， qǐng qián wǎng èr lóu zhěn shì děng hòu。','Đã đăng ký thành công cho em rồi, em lên phòng khám tầng hai chờ nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L322_07','V322','阮明',7,'好的，谢谢你！','hǎo de， xiè xiè nǐ！','Dạ vâng, em cảm ơn chị!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT323','S109','Miêu tả triệu chứng với bác sĩ',NULL,'B1');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V323','SIT323','P1','suon_se','ban_chinh_thuc',NULL,'就医时清晰说明症状时长、频率和状态，能帮助医生快速、精准判断病情。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_01','V323','阮明',1,'医生您好，我这三四天一直头晕、浑身没力气。','yī shēng nín hǎo， wǒ zhè sān sì tiān yì zhí tóu yūn、 hún shēn méi lì qì。','Chào bác sĩ, mấy hôm nay em cứ bị chóng mặt, người mệt rã rời ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_02','V323','医生',2,'是一直晕，还是偶尔一阵一阵的？','shì yì zhí yūn， hái shì ǒu ěr yī zhèn yī zhèn de？','Chóng mặt liên tục hay thỉnh thoảng mới bị từng cơn vậy con?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_03','V323','阮明',3,'偶尔发作，尤其是晚上，还经常失眠睡不着。','ǒu ěr fā zuò， yóu qí shì wǎn shàng， hái jīng cháng shī mián shuì bù zhe。','Thỉnh thoảng thôi ạ, nhất là buổi tối, với lại em hay mất ngủ không ngủ được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_04','V323','医生',4,'有没有发烧、恶心或者其他不舒服？','yǒu méi yǒu fā shāo、 ě xīn huò zhě qí tā bù shū fú？','Có sốt, buồn nôn hay khó chịu gì khác không con?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_05','V323','阮明',5,'没有的，就只有头晕和乏力这两个症状。','méi yǒu de， jiù zhǐ yǒu tóu yūn hé fá lì zhè liǎng gè zhèng zhuàng。','Dạ không ạ, chỉ có hai triệu chứng chóng mặt với mệt mỏi này thôi.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_06','V323','医生',6,'我大概清楚了，我给你简单检查一下。','wǒ dà gài qīng chǔ le， wǒ gěi nǐ jiǎn dān jiǎn chá yī xià。','Bác cũng hiểu sơ sơ rồi, để bác khám nhanh cho con một chút.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L323_07','V323','阮明',7,'好的，麻烦医生了！','hǎo de， má fán yī shēng le！','Dạ vâng, phiền bác sĩ giúp em với ạ!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT324','S109','Báo dị ứng thuốc trước khi được kê đơn',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V324','SIT324','P1','suon_se','chinh_thuc',NULL,'国内就医开药必须主动申报过敏史，是保障用药安全的重要医疗规范。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_01','V324','阮明',1,'医生，我需要提前告知您我的药物过敏史。','yī shēng， wǒ xū yào tí qián gào zhī nín wǒ de yào wù guò mǐn shǐ。','Thưa bác sĩ, tôi cần thông báo trước với bác sĩ về tiền sử dị ứng thuốc của mình.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_02','V324','医生',2,'好的，你具体对哪种药物过敏？','hǎo de， nǐ jù tǐ duì nǎ zhǒng yào wù guò mǐn？','Được ạ, anh/chị dị ứng cụ thể với loại thuốc nào?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_03','V324','阮明',3,'我对青霉素类药物过敏，绝对不能使用这类药。','wǒ duì qīng méi sù lèi yào wù guò mǐn， jué duì bù néng shǐ yòng zhè lèi yào。','Tôi dị ứng với các loại thuốc thuộc nhóm penicillin, tuyệt đối không được dùng nhóm thuốc này.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_04','V324','医生',4,'我记下了，开药时会完全避开致敏药物。','wǒ jì xià le， kāi yào shí huì wán quán bì kāi zhì mǐn yào wù。','Tôi đã ghi nhận rồi, khi kê đơn sẽ tránh hoàn toàn các loại thuốc gây dị ứng đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_05','V324','阮明',5,'我之前过敏反应很严重，所以特别谨慎。','wǒ zhī qián guò mǐn fǎn yìng hěn yán zhòng， suǒ yǐ tè bié jǐn shèn。','Trước đây tôi từng bị phản ứng dị ứng rất nặng, nên tôi đặc biệt thận trọng.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_06','V324','医生',6,'我明白，用药安全是第一位的，你放心。','wǒ míng bái， yòng yào ān quán shì dì yī wèi de， nǐ fàng xīn。','Tôi hiểu, an toàn dùng thuốc là ưu tiên hàng đầu, anh/chị cứ yên tâm.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L324_07','V324','阮明',7,'感谢医生细心负责！','gǎn xiè yī shēng xì xīn fù zé！','Cảm ơn bác sĩ đã chu đáo và tận tâm!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT325','S110','Mua thuốc theo đơn tại nhà thuốc',NULL,'A2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V325','SIT325','P1','suon_se','ban_chinh_thuc',NULL,'医院取药后，药师会逐一告知用法、用量、保存方式，务必严格遵照执行。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_01','V325','阮明',1,'你好，这是我的处方单，麻烦帮我取一下药。','nǐ hǎo， zhè shì wǒ de chǔ fāng dān， má fán bāng wǒ qǔ yī xià yào。','Chào anh, đây là đơn thuốc của em, phiền anh lấy thuốc giúp em với ạ.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_02','V325','药师',2,'好的，请稍等，我核对一下药品信息。','hǎo de， qǐng shāo děng， wǒ hé duì yī xià yào pǐn xìn xī。','Được rồi, em chờ chút nhé, để anh kiểm tra lại thông tin thuốc.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_03','V325','阮明',3,'没问题，这些药具体怎么服用呀？','méi wèn tí， zhè xiē yào jù tǐ zěn me fú yòng ya？','Dạ không sao ạ, mấy loại thuốc này dùng cụ thể thế nào vậy anh?','AM01');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_04','V325','药师',4,'都是一日三次，饭后温水服用，说明书也有标注。','dōu shì yī rì sān cì， fàn hòu wēn shuǐ fú yòng， shuō míng shū yě yǒu biāo zhù。','Đều uống ngày ba lần, sau bữa ăn với nước ấm, trên tờ hướng dẫn cũng có ghi rồi đó.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_05','V325','阮明',5,'需要低温冷藏保存吗？','xū yào dī wēn lěng cáng bǎo cún ma？','Có cần bảo quản lạnh không anh?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_06','V325','药师',6,'不用，常温避光存放就可以。','bù yòng， cháng wēn bì guāng cún fàng jiù kě yǐ。','Không cần đâu, cứ để nơi thoáng mát tránh ánh sáng là được.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L325_07','V325','阮明',7,'明白了，谢谢药师！','míng bái le， xiè xiè yào shī！','Dạ em hiểu rồi, cảm ơn anh nhé!',NULL);
INSERT INTO situations (id,subdomain_id,name,description,difficulty_level) VALUES ('SIT326','S109','Hỏi bảo hiểm có chi trả loại thuốc này không',NULL,'B2');
INSERT INTO dialogue_variants (id,situation_id,persona_id,outcome_type,register_level,context_note,cultural_note) VALUES ('V326','SIT326','P1','twist','ban_chinh_thuc',NULL,'国内医保仅覆盖基础刚需药品，进口药、高端特效药大多需要个人自费。');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_01','V326','阮明',1,'你好，我想问一下我开的这些药能不能医保报销？','nǐ hǎo， wǒ xiǎng wèn yī xià wǒ kāi de zhè xiē yào néng bù néng yī bǎo bào xiāo？','Chào chị, em muốn hỏi mấy loại thuốc bác sĩ kê cho em có được bảo hiểm y tế chi trả không ạ?',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_02','V326','工作人员',2,'我帮你查询一下药品医保目录。','wǒ bāng nǐ chá xún yī xià yào pǐn yī bǎo mù lù。','Để chị tra danh mục thuốc bảo hiểm y tế giúp em nhé.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_03','V326','工作人员',3,'查到了，其中两款基础药可以报销，一款进口药不行。','chá dào le， qí zhōng liǎng kuǎn jī chǔ yào kě yǐ bào xiāo， yī kuǎn jìn kǒu yào bù xíng。','Tra ra rồi nè, trong đó có hai loại thuốc cơ bản được bảo hiểm chi trả, còn một loại thuốc nhập khẩu thì không.',NULL);
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_04','V326','阮明',4,'这样啊，进口药需要全额自费是吗？','zhè yàng a， jìn kǒu yào xū yào quán é zì fèi shì ma？','Vậy à, tức là thuốc nhập khẩu em phải tự chi trả toàn bộ đúng không chị?','AM05');
INSERT INTO dialogue_lines (id,variant_id,speaker,order_index,text_zh,pinyin,text_vi,attitude_marker_id) VALUES ('L326_05','V326','工作人员',5,'对的，进口特效药不在医保报销范围内。','duì de， jìn kǒu tè xiào yào bù zài yī bǎo bào xiāo fàn wéi nèi。','Đúng rồi, thuốc đặc trị nhập khẩu không nằm trong phạm vi chi trả của bảo hiểm y tế.',NULL);
